fn copy_source() -> Bytes {
  let out = Bytes::new()
  Bytes::fill(out, 37, 4194304)
  Bytes::set(out, 0, 19)
  Bytes::set(out, 4194303, 83)
  out
}

let source = copy_source()

bench "copy_blit" {
  let dst = Bytes::new()
  Bytes::blit(dst, source, 0, Bytes::length(source))
  assert(Bytes::length(dst) == 4194304)
  assert(Bytes::get(dst, 0) == 19)
  assert(Bytes::get(dst, 4194303) == 83)
}

bench "copy_append" {
  let dst = Bytes::new()
  Bytes::append(dst, source)
  assert(Bytes::length(dst) == 4194304)
  assert(Bytes::get(dst, 0) == 19)
  assert(Bytes::get(dst, 4194303) == 83)
}

test "whole-range blit and append produce identical bytes" {
  let a = Bytes::new()
  let b = Bytes::new()
  Bytes::blit(a, source, 0, Bytes::length(source))
  Bytes::append(b, source)
  assert(a == b)
}

effect_microbenchmark.source:
import @vibe/compiler/core { Expr }
import @vibe/compiler/lowering/effects/queries { EdpReadQuery, edp_rq_fold, edp_performing_names }
import @vibe/core { struct MutSet }

fn names_and_bodies(size: Int) -> (Array[String], Array[Option[Expr]]) {
  let names: Array[String] = []
  let bodies: Array[Option[Expr]] = []
  let mut i = 0
  while i < size {
    Array::push(names, "f" + Int::to_string(i))
    let mut body = if i + 1 == size {
      ECall(EIdent("perform", -1), [ECall(EIdent("Ask::Get", -1), [], -1)], -1)
    } else {
      ECall(EIdent("f" + Int::to_string(i + 1), -1), [], -1)
    }
    let mut j = 0
    while j < 16 { body = ESeq(EInt(j), body); j = j + 1 }
    Array::push(bodies, Some(body))
    i = i + 1
  }
  (names, bodies)
}
fn set_of(names: Array[String]) -> MutSet[String] {
  let out: MutSet[String] = MutSet::new_string()
  for name in names { MutSet::add(out, name) }
  out
}
let graph = names_and_bodies(64)
let names = graph.0
let bodies = graph.1
let known = set_of(names)
let inert = set_of(["Ask::Get"])

fn previous() -> Array[String] {
  let member: MutSet[String] = MutSet::new_string()
  let out: Array[String] = []
  let q_perform = RQPerformsUserEffect("Ask")
  let q_opaque = RQOpaqueCall(inert, known)
  let mut i = 0
  while i < Array::length(names) {
    match Array::get(bodies, i) {
      Some(body) => if edp_rq_fold(q_perform, body) > 0 || edp_rq_fold(q_opaque, body) > 0 {
        MutSet::add(member, Array::get(names, i))
        Array::push(out, Array::get(names, i))
      },
      None => ()
    }
    i = i + 1
  }
  let q_calls = RQCallsAny(member)
  let mut grew = true
  while grew {
    grew = false
    let mut j = 0
    while j < Array::length(names) {
      let name = Array::get(names, j)
      if !MutSet::has(member, name) {
        match Array::get(bodies, j) {
          Some(body) => if edp_rq_fold(q_calls, body) > 0 {
            MutSet::add(member, name)
            Array::push(out, name)
            grew = true
          },
          None => ()
        }
      }
      j = j + 1
    }
  }
  out
}
bench "effect_previous" { assert(Array::length(previous()) == 64) }
bench "effect_worklist" { assert(Array::length(edp_performing_names(names, bodies, "Ask", inert, known)) == 64) }
test "query iteration and worklist agree" { assert(previous() == edp_performing_names(names, bodies, "Ask", inert, known)) }

